<template>
  <main class="learning-records">
    <header class="records-heading"><div><h1>实验学习记录</h1></div><button :disabled="loading" @click="records.load">刷新记录</button></header>
    <nav class="record-filters" aria-label="实验记录分类"><button v-for="filter in recordKinds" :key="filter.id" :class="{ active: kind === filter.id }" :aria-pressed="kind === filter.id" @click="records.setKind(filter.id)">{{ filter.label }} <span>{{ counts[filter.id] || 0 }}</span></button></nav>
    <div v-if="error" class="record-error" role="alert">{{ error }} <button @click="records.load">重新加载</button></div>
    <section v-loading="loading" class="record-list" aria-label="我的实验记录" :aria-busy="loading">
      <article v-for="record in items" :key="record.key" class="record-card">
        <div class="record-summary"><div class="record-title"><span class="kind-tag">{{ record.kind_label }}</span><span v-if="record.preview" class="preview-tag">教师预览</span><span class="status-label">{{ record.status_label }}</span><h2>{{ record.title }}</h2><time>{{ timeText(record.updated_at || record.started_at) }}</time></div><strong class="record-score">{{ scoreText(record) }}</strong></div>
        <div class="record-bottom"><span>{{ operationCountText(record) }}</span><span :class="{ 'has-errors': record.error_count > 0 }">{{ errorCountText(record) }}</span><button @click="open(record)">查看过程与反馈 →</button></div>
      </article>
      <el-empty v-if="!loading && !error && !items.length" description="暂无此类实验记录"><router-link to="/student/lab-topics">进入实验专题 →</router-link></el-empty>
    </section>
    <el-pagination v-if="total > 20" class="records-pagination" :current-page="page" :page-size="20" :total="total" layout="prev, pager, next, total" @current-change="records.setPage" />
    <el-drawer v-model="drawerOpen" :title="selected?.title || '实验记录'" size="min(760px, 96vw)" destroy-on-close>
      <div v-loading="detailLoading" class="record-detail" :aria-busy="detailLoading">
        <div v-if="detailError" class="record-error" role="alert">{{ detailError }} <button @click="records.open(selected)">重试</button></div>
        <template v-if="detail">
          <div class="detail-summary"><div><span>{{ detail.kind_label }} · {{ detail.status_label }}</span><time>{{ timeText(detail.started_at) }}</time></div><strong>{{ scoreText(detail) }}</strong></div>
          <router-link v-if="detail.continue_path?.startsWith('/student/')" class="source-link" :to="detail.continue_path" @click="drawerOpen = false">{{ detail.kind === 'simulation' ? '进入仿真操作台' : '进入原实验 / 回放' }} →</router-link>
          <nav class="detail-tabs" aria-label="记录详情分类"><button :class="{active:detailTab==='operations'}" :aria-pressed="detailTab==='operations'" @click="detailTab='operations'">操作过程 {{ detail.operations?.length || 0 }}</button><button :class="{active:detailTab==='feedback'}" :aria-pressed="detailTab==='feedback'" @click="detailTab='feedback'">错误与教学反馈 {{ detail.errors?.length || 0 }}</button></nav>
          <template v-if="detailTab === 'operations'">
            <ol v-if="detail.operations?.length" class="operation-timeline"><li v-for="(operation,index) in detail.operations" :key="operation.id || index" :class="{rejected:operation.accepted===false}"><span class="step-number">{{ operation.sequence || index+1 }}</span><div><div class="operation-title"><strong>{{ operationLabel(operation.action) }}<span v-if="operation.target"> · {{ operation.target }}</span></strong><time>{{ timeText(operation.time) }}</time></div><p>{{ operation.message }}</p><span v-if="operation.accepted===false" class="operation-state">操作未执行</span><span v-else-if="operation.accepted===true" class="operation-state accepted">已执行</span></div></li></ol>
            <p v-else class="empty-note">本记录未采集逐步操作，可在“错误与教学反馈”查看已保存的提交结果。</p>
          </template>
          <section v-else class="teaching-feedback" aria-label="错误与教学反馈">
            <div v-if="detail.errors?.length" class="error-points"><h2>{{ '错误点' }}</h2><article v-for="(item,index) in detail.errors" :key="index"><strong>{{ item.label }}</strong><p>{{ item.message }}</p><p v-if="item.correction" class="correction">{{ item.correction }}</p><span v-if="item.devices?.length" class="related-devices">相关设备：{{ item.devices.join('、') }}</span></article></div>
            <p v-else class="empty-note">{{ detail.status === 'in_progress' && detail.score == null ? '本次实验尚未形成最终评分。' : '本记录暂无已判定的错误点。' }}</p>
            <article v-for="(feedback,index) in detail.feedback || []" :key="index" class="feedback-card" :class="{ 'ai-feedback': feedback.source === 'ai' }"><span class="feedback-source">{{ feedbackLabel(feedback.source) }}</span><h3 v-if="feedback.title">{{ feedback.title }}</h3><p>{{ feedback.text }}</p><time v-if="feedback.time">{{ timeText(feedback.time) }}</time></article>
            <p v-if="!detail.feedback?.length" class="empty-note">本记录尚无教学解析或教师评语。</p>
            <article v-if="detail.notes" class="feedback-card"><span class="feedback-source">学生观察记录</span><p>{{ detail.notes }}</p></article>
          </section>
        </template>
      </div>
    </el-drawer>
  </main>
</template>
<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import request from '@/utils/request'
import { createLearningRecords, recordKinds, scoreText, timeText, operationLabel, feedbackLabel, operationCountText, errorCountText } from './useLearningRecords.js'
const route = useRoute(), records = createLearningRecords({ get: (url, config) => request.get(url, config) })
const { items, counts, total, kind, page, loading, error, selected, detail, detailLoading, detailError } = records
const detailTab = ref('operations')
const drawerOpen = computed({ get: () => Boolean(selected.value), set: value => { if (!value) records.close() } })
function open(record) { detailTab.value = 'operations'; records.open(record) }
onMounted(async () => { await records.setKind(route.query.kind || 'all'); if (route.query.record && route.query.kind) open({ kind: route.query.kind, record_id: route.query.record }) })
onBeforeUnmount(records.dispose)
</script>
<style scoped>
.learning-records{max-width:1200px;margin:auto;color:#183b58}.records-heading{display:flex;justify-content:space-between;align-items:center;gap:18px;margin-bottom:22px}.eyebrow{font-size:10px;color:#0075b7;letter-spacing:1.5px}.records-heading h1{font-size:27px;margin:5px 0 8px;font-weight:600}.records-heading p{color:#718697;font-size:13px;margin:0}.learning-records button,.record-detail button{font:inherit;border:1px solid #d4e1ea;background:#fff;border-radius:5px;color:#466b86;padding:9px 14px;cursor:pointer;font-size:13px}.learning-records button:disabled{opacity:.5;cursor:wait}.record-filters{display:flex;gap:8px;flex-wrap:wrap;border-bottom:1px solid #dfe8ef;margin-bottom:17px;padding-bottom:14px}.record-filters button{border-color:transparent;background:transparent}.record-filters button.active{border-color:#c9dfed;color:#0075b7;background:#eaf3f9}.record-filters button span{font-size:11px;margin-left:7px;opacity:.75}.record-list{display:grid;gap:13px;min-height:120px}.record-card{background:#fff;border:1px solid #dce6ee;border-radius:8px;padding:18px 20px}.record-summary{display:flex;justify-content:space-between;align-items:center;gap:20px}.kind-tag{font-size:11px;color:#0075b7;background:#edf5fa;padding:4px 7px;border-radius:3px}.preview-tag{font-size:11px;margin-left:7px;color:#8e7c4b}.status-label{font-size:11px;margin-left:9px;color:#7890a0}.record-title h2{font-size:17px;font-weight:500;line-height:1.6;margin:11px 0 6px}.record-title time{font-size:11px;color:#8294a1}.record-score{font-size:18px;font-weight:500;text-align:right;color:#356d8c;max-width:40%;line-height:1.7}.record-bottom{display:flex;align-items:center;gap:18px;border-top:1px solid #eaf0f5;margin-top:15px;padding-top:11px;color:#7a8e9c;font-size:12px}.record-bottom .has-errors{color:#b26545}.record-bottom button{margin-left:auto;color:#0075b7;border:0;padding:5px 0}.record-error{background:#fff3ef;color:#a75c43;padding:12px 15px;border-radius:5px;margin-bottom:14px;font-size:13px}.record-error button{margin-left:12px}.records-pagination{margin-top:20px;justify-content:center}.record-detail{min-height:160px;color:#2c4c65}.detail-summary{display:flex;align-items:center;justify-content:space-between;gap:18px;padding-bottom:15px;border-bottom:1px solid #e6edf3}.detail-summary span{font-size:13px;color:#658195}.detail-summary time{display:block;font-size:11px;color:#8597a3;margin-top:7px}.detail-summary strong{font-size:21px;color:#306d8c;font-weight:500}.source-link{display:inline-block;color:#0075b7;font-size:13px;margin:17px 0 4px}.detail-tabs{display:flex;gap:9px;padding:15px 0;margin-bottom:8px}.detail-tabs button{background:#f4f7fa;border-color:transparent}.detail-tabs button.active{background:#e6f2f9;border-color:#c8e0ee;color:#0075b7}.operation-timeline{list-style:none;margin:0;padding:0}.operation-timeline li{display:flex;gap:14px;padding:16px 0;border-bottom:1px solid #e8eff4}.operation-timeline li>div{flex:1;min-width:0}.step-number{display:grid;place-items:center;flex-shrink:0;width:26px;height:26px;border-radius:50%;background:#edf4f9;color:#7293aa;font-size:12px}.operation-title{display:flex;align-items:baseline;justify-content:space-between;gap:12px}.operation-title strong{font-size:14px;font-weight:500;line-height:1.7;overflow-wrap:anywhere}.operation-title time{font-size:10px;color:#8a9ba8;white-space:nowrap}.operation-timeline p{font-size:13px;line-height:1.85;margin:7px 0;white-space:pre-wrap;overflow-wrap:anywhere;color:#617b8f}.operation-state{font-size:11px;color:#ab6b4d}.operation-state.accepted{color:#5b8c76}.rejected .step-number{background:#fff0e6;color:#b27350}.empty-note{font-size:13px;color:#8193a0;line-height:1.9;margin:18px 0}.error-points h2{font-size:16px;font-weight:500;margin:17px 0}.error-points article{border-left:3px solid #d69a76;background:#fffaf7;padding:14px 16px;margin-bottom:12px}.error-points strong{font-size:14px;font-weight:500}.error-points p,.feedback-card p{font-size:13px;line-height:1.9;margin:9px 0;white-space:pre-wrap;overflow-wrap:anywhere}.error-points .correction{color:#34815e}.related-devices{font-size:11px;color:#8799a6}.feedback-card{padding:17px;border:1px solid #dfe8ef;border-radius:7px;margin:15px 0;background:#f8fafc}.feedback-card.ai-feedback{background:#f0f7fb;border-color:#c3deec}.feedback-source{font-size:11px;color:#4582a5}.feedback-card h3{font-size:15px;font-weight:500;line-height:1.7;margin:10px 0}.feedback-card time{font-size:10px;color:#8c9ba5}.learning-records :is(a,button):focus-visible,.record-detail :is(a,button):focus-visible{outline:3px solid #0075b7;outline-offset:3px}@media(max-width:600px){.records-heading{align-items:flex-start;gap:10px}.records-heading h1{font-size:23px}.records-heading p{max-width:220px;line-height:1.8}.records-heading>button{padding:8px 11px;white-space:nowrap}.record-filters{gap:4px}.record-filters button{padding:8px 9px;font-size:12px}.record-card{padding:15px}.record-summary{align-items:flex-start;gap:10px}.record-score{font-size:15px;max-width:35%}.record-title h2{font-size:15px}.record-bottom{gap:10px;font-size:11px}.record-bottom button{font-size:12px}.operation-title{flex-direction:column;gap:3px}.operation-timeline li{gap:10px}}
</style>
